g=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
from collections import deque
R,C=len(g),len(g[0]); seen=set(); q=deque()
for r in range(R):
 for c in range(C):
  if (r in (0,R-1) or c in (0,C-1)) and g[r][c]==0 and (r,c) not in seen: seen.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
  x,y=r+dr,c+dc
  if 0<=x<R and 0<=y<C and g[x][y]==0 and (x,y) not in seen:seen.add((x,y));q.append((x,y))
holes=[(r,c) for r in range(R) for c in range(C) if g[r][c]==0 and (r,c) not in seen]
print(holes)
